const sectionAliases: Record<string,string[]> = {
  experience:['experience','work experience','professional experience','employment','employment history','work history','professional background'],
  education:['education','academic background'],
  skills:['skills','core competencies','technical skills','expertise'],
  certifications:['certifications','licenses','certificates'],
  projects:['projects','selected projects','portfolio'],
  summary:['summary','professional summary','profile','professional profile','career summary']
};
const escapeRegExp=(value:string)=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const isHeader=(line:string, aliases:string[])=>aliases.some(a=>new RegExp(`^${escapeRegExp(a)}\\s*:?\\s*$`,'i').test(line.trim()));

function section(text:string, aliases:string[]) {
  const lines=text.split(/\r?\n/), start=lines.findIndex(l=>isHeader(l,aliases));
  if(start<0) return [];
  const result:string[]=[];
  const allHeaders=Object.values(sectionAliases).flat();
  for(let i=start+1;i<lines.length;i++){
    const line=lines[i].trim();
    if(!line) continue;
    if(isHeader(line,allHeaders)) break;
    result.push(line.replace(/^[•●▪‣*-]\s*/,''));
  }
  return result;
}
function containsTerm(text:string,term:string) {
  return new RegExp(`(?:^|[^a-z0-9])${escapeRegExp(term).replace(/\s+/g,'\\s+')}(?=$|[^a-z0-9])`,'i').test(text);
}

export function parseResumeText(rawText:string, formattingIssues:string[]=[], formatInspectionAvailable=false):ParsedResume {
  const text=rawText.replace(/\r/g,'').trim();
  const lines=text.split('\n').map(x=>x.trim()).filter(Boolean);
  const email=text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0]??'';
  const phone=text.match(/(?:\+?\d[\d\s().-]{7,}\d)/)?.[0]?.trim()??'';
  const linkedin=text.match(/(?:https?:\/\/)?(?:www\.)?linkedin\.com\/in\/[A-Z0-9-_%]+/i)?.[0]??'';
  const headers=Object.values(sectionAliases).flat();
  const first=lines.slice(0,6).find(l=>l.length<60&&!/@|linkedin|resume|curriculum/i.test(l)&&!/\d{3}/.test(l)&&!isHeader(l,headers))??'';
  const skills=SKILL_BANK.filter(s=>containsTerm(text,s));
  const get=(key:string)=>section(text,sectionAliases[key]);
  return {name:first,email,phone,linkedin,skills,education:get('education'),experience:get('experience'),certifications:get('certifications'),projects:get('projects'),rawText:text,formattingIssues,formatInspectionAvailable};
}

function readZipEntry(bytes:Uint8Array,path:string):Promise<string|null> {
  return (async()=>{
    const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);
    let eocd=-1;
    for(let i=Math.max(0,bytes.length-65_557);i<=bytes.length-22;i++){
      if(view.getUint32(i,true)===0x06054b50){eocd=i;break}
    }
    if(eocd<0)return null;
    const entries=view.getUint16(eocd+10,true),centralOffset=view.getUint32(eocd+16,true);
    let offset=centralOffset;
    for(let entry=0;entry<entries;entry++){
      if(view.getUint32(offset,true)!==0x02014b50)return null;
      const method=view.getUint16(offset+10,true),compressedSize=view.getUint32(offset+20,true);
      const nameLength=view.getUint16(offset+28,true),extraLength=view.getUint16(offset+30,true),commentLength=view.getUint16(offset+32,true);
      const localOffset=view.getUint32(offset+42,true);
      const name=new TextDecoder().decode(bytes.slice(offset+46,offset+46+nameLength));
      if(name===path){
        const localNameLength=view.getUint16(localOffset+26,true),localExtraLength=view.getUint16(localOffset+28,true);
        const start=localOffset+30+localNameLength+localExtraLength,compressed=bytes.slice(start,start+compressedSize);
        let result:ArrayBuffer;
        if(method===0)result=compressed.buffer.slice(compressed.byteOffset,compressed.byteOffset+compressed.byteLength);
        else if(method===8){
          const stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
          result=await new Response(stream).arrayBuffer();
        } else return null;
        return new TextDecoder().decode(result);
      }
      offset+=46+nameLength+extraLength+commentLength;
    }
    return null;
  })().catch(()=>null);
}

async function inspectDocx(file:File,html:string):Promise<{issues:string[];available:boolean}> {
  const issues:string[]=[];
  if(/<table\b/i.test(html))issues.push('A table was found; complex tables can be read out of order by some ATS tools.');
  if(/<img\b/i.test(html))issues.push('An image was found; keep important details as selectable text.');
  const bytes=new Uint8Array(await file.arrayBuffer());
  const [documentXml,stylesXml]=await Promise.all([readZipEntry(bytes,'word/document.xml'),readZipEntry(bytes,'word/styles.xml')]);
  if(!documentXml)return {issues,available:false};
  if(/<w:cols\b[^>]*w:num=["']([2-9])["']/i.test(documentXml)||((documentXml.match(/<w:col\b/g)??[]).length>1))issues.push('Multiple document columns were detected; a single-column layout is safer for ATS parsing.');
  if(/<w:(?:drawing|pict)\b/i.test(documentXml))issues.push('Images or drawing objects were found; avoid placing contact details or qualifications inside graphics.');
  const fontMatches=[...`${documentXml}\n${stylesXml??''}`.matchAll(/<w:rFonts\b[^>]*?w:(?:ascii|hAnsi)=["']([^"']+)["'][^>]*\/?>/gi)].map(match=>match[1].trim());
  const allowed=new Set(['arial','calibri','aptos','times new roman','cambria','georgia','helvetica','verdana','tahoma']);
  const unusual=[...new Set(fontMatches.filter(font=>font&&!allowed.has(font.toLowerCase())))];
  if(unusual.length)issues.push(`Non-standard font${unusual.length>1?'s':''} detected: ${unusual.slice(0,3).join(', ')}.`);
  return {issues,available:true};
}

export async function extractResume(file:File):Promise<ParsedResume> {
  if(file.size>10*1024*1024) throw new Error('This file is over 10 MB. Choose a smaller resume file.');
  const ext=file.name.split('.').pop()?.toLowerCase();
  let text='',formattingIssues:string[]=[],formatInspectionAvailable=false;
  if(ext==='txt') text=await file.text();
  else if(ext==='pdf'){
    const pdfjs=await import('pdfjs-dist/legacy/build/pdf.mjs');
    const data=new Uint8Array(await file.arrayBuffer());
    const doc=await pdfjs.getDocument({data,disableWorker:true,isEvalSupported:false}).promise;
    const pages:string[]=[];
    let possibleColumnRows=0,hasImage=false;
    for(let i=1;i<=doc.numPages;i++){
      const page=await doc.getPage(i),content=await page.getTextContent();
      const rows=new Map<number,{x:number;text:string}[]>();
      for(const item of content.items as any[]){
        if(!('str' in item)||!item.str.trim())continue;
        const x=Number(item.transform?.[4]??0),y=Number(item.transform?.[5]??0),row=Math.round(y/2);
        const group=rows.get(row)??[];group.push({x,text:item.str});rows.set(row,group);
      }
      for(const group of rows.values()){
        const ordered=group.sort((a,b)=>a.x-b.x);
        if(ordered.length>1&&ordered.some((part,index)=>index>0&&part.x-ordered[index-1].x>130))possibleColumnRows++;
      }
      pages.push([...rows.entries()].sort(([a],[b])=>b-a).map(([,row])=>row.sort((a,b)=>a.x-b.x).map(item=>item.text).join(' ')).join('\n'));
      try{
        const operators=await page.getOperatorList();
        const pdfOperators=(pdfjs as any).OPS;
        const imageOps=[pdfOperators?.paintImageXObject,pdfOperators?.paintImageXObjectRepeat,pdfOperators?.paintInlineImageXObject,pdfOperators?.paintImageMaskXObject].filter(Number.isFinite);
        hasImage=hasImage||operators.fnArray.some((op:number)=>imageOps.includes(op));
      }catch{/* Some PDF variants do not expose image operators; text extraction can still proceed. */}
    }
    text=pages.join('\n');
    if(possibleColumnRows>=6)formattingIssues.push('Text appears to use multiple columns; ATS readers may mix the reading order.');
    if(hasImage)formattingIssues.push('The PDF contains image content; make sure important details are also selectable text.');
    formatInspectionAvailable=true;
  } else if(ext==='docx'){
    const imported=await import('mammoth/mammoth.browser');
    const mammoth=(imported as any).default??imported;
    const bytes=await file.arrayBuffer();
    const [result,html]=await Promise.all([mammoth.extractRawText({arrayBuffer:bytes}),mammoth.convertToHtml({arrayBuffer:bytes})]);
    text=result.value;
    const inspection=await inspectDocx(file,html.value);
    formattingIssues=inspection.issues;formatInspectionAvailable=inspection.available;
  } else throw new Error('Choose a PDF, DOCX, or TXT resume.');
  if(text.trim().length<40) throw new Error('We could not find enough readable text. Try a text-based PDF or DOCX.');
  return parseResumeText(text,formattingIssues,formatInspectionAvailable);
}